"""
Unit test that verifies the existence of root‑level metadata JSON files
for the first few BA instances and that they contain the required
``metrics`` field.

This test is specific to task T006 and does not interfere with existing
tests.
"""

import json
from pathlib import Path

from llmxive_toolkit import paths

def _load_metadata(path: Path):
    with path.open("r") as f:
        return json.load(f)

def test_root_metadata_contains_metrics():
    # Check a couple of BA instances that should have been generated by the helper script.
    for idx in (0, 1):
        meta_path = paths.data("raw", "networks", f"metadata_BA_{idx:04d}.json")
        assert meta_path.is_file(), f"Missing metadata file: {meta_path}"
        data = _load_metadata(meta_path)
        # Required top‑level keys
        for key in ("topology", "seed", "node_count", "edge_count", "metrics"):
            assert key in data, f"Key {key} missing in {meta_path}"
        # Verify metric keys
        metric_keys = {
            "assortativity",
            "average_path_length",
            "clustering_coefficient",
            "num_nodes",
            "num_edges",
        }
        assert metric_keys.issubset(data["metrics"].keys()), "Incomplete metrics"